    pp_s1_title:                  "Informations que nous collectons",
    pp_s1_body:                   "Nous collectons les informations que vous fournissez lors de la création d'un profil : nom, âge, photos et préférences. Nous collectons également des données d'utilisation pour améliorer le service.",
    pp_s2_title:                  "Comment nous utilisons vos informations",
    pp_s2_body:                   "Vos informations servent à vous connecter avec des personnes compatibles et à assurer la sécurité sur la plateforme. Nous ne vendons pas vos données personnelles à des tiers.",
