    tip_voice_call_title:         "Commencez par un appel vocal",
    tip_voice_call_body:          "Le système d'appel structuré de Lulou vous permet d'entendre la voix de quelqu'un avant de vous rencontrer.",
    tip_red_flags_title:          "Faites confiance aux signaux d'alarme",
