    mp_07_body:                   "Signalez tout ce qui semble anormal. Bloquez le harcèlement immédiatement.",
    lic_intro:                    "Lulou Dating est construit avec des logiciels open source. Nous reconnaissons avec gratitude les projets suivants :",
