    pp_s1_title:                  "Informationen, die wir sammeln",
    pp_s1_body:                   "Wir sammeln Informationen, die du bei der Profilanlegung angibst: Name, Alter, Fotos und Präferenzen. Wir sammeln auch Nutzungsdaten zur Serviceverbesserung.",
    pp_s2_title:                  "Wie wir deine Informationen verwenden",
    pp_s2_body:                   "Deine Daten dienen dazu, dich mit passenden Personen zu verbinden und die Sicherheit auf der Plattform zu gewährleisten. Wir verkaufen deine Daten nicht an Dritte.",
    pp_s3_title:                  "Fotos und Medien",
    pp_s3_body:                   "Hochgeladene Fotos werden sicher gespeichert. Profilfotos sind für andere Mitglieder sichtbar.",
    pp_s4_title:                  "Datenspeicherung",
    pp_s4_body:                   "Deine Daten werden gespeichert, solange dein Konto aktiv ist. Bei Kontolöschung werden deine Daten innerhalb von 30 Tagen gelöscht.",
    pp_s5_title:                  "Deine Rechte",
    pp_s5_body:                   "Du hast jederzeit das Recht, auf deine Daten zuzugreifen, sie zu korrigieren oder zu löschen. Du kannst eine Kopie über die Einstellungen herunterladen.",
    pp_s6_title:                  "Kontakt",
    pp_s6_body:                   "Fragen zu dieser Richtlinie? Schreibe uns an privacy@lulou.dating.",
    tos_s1_title:                 "Annahme der Bedingungen",
    tos_s1_body:                  "Durch die Erstellung eines Kontos bei Lulou stimmst du diesen Nutzungsbedingungen zu.",
    tos_s2_title:                 "Berechtigung",
    tos_s2_body:                  "Du musst mindestens 18 Jahre alt sein, um Lulou zu nutzen.",
    tos_s3_title:                 "Akzeptable Nutzung",
    tos_s3_body:                  "Alle Mitglieder respektvoll behandeln und die Plattform nicht für Belästigung oder illegale Aktivitäten nutzen.",
    tos_s4_title:                 "Inhaltseigentum",
    tos_s4_body:                  "Du behältst das Eigentum an den Fotos und Inhalten, die du hochlädst.",
    tos_s5_title:                 "Kündigung",
    tos_s5_body:                  "Wir können Konten sperren, die gegen diese Bedingungen verstoßen. Du kannst dein Konto jederzeit löschen.",
    tos_s6_title:                 "Kontakt",
    tos_s6_body:                  "Fragen? Schreibe an legal@lulou.dating.",
    export_data_title:            "Persönliche Daten exportieren",
    export_data_desc:             "Lade eine JSON-Datei mit deinen Profilinformationen, Präferenzen und Kontodetails herunter.",
    tip_voice_call_title:         "Mit einem Sprachanruf beginnen",
    tip_voice_call_body:          "Das strukturierte Anrufsystem von Lulou ermöglicht es dir, jemandes Stimme zu hören, bevor du dich triffst.",
    tip_red_flags_title:          "Warnsignalen vertrauen",
    tip_red_flags_body:           "Wenn jemand dich unter Druck setzt, Kontaktdaten zu teilen, Geld fordert oder dich unwohl fühlen lässt, blockiere und melde ihn.",
    tip_public_title:             "Zuerst in der Öffentlichkeit treffen",
    tip_public_body:              "Wähle immer einen belebten öffentlichen Ort für ein erstes Treffen. Informiere einen Freund über deinen Aufenthaltsort.",
    tip_transport_title:          "Eigenen Transport organisieren",
    tip_transport_body:           "Fahre selbst, nutze öffentliche Verkehrsmittel oder ruf dir ein Taxi.",
    tip_share_plans_title:        "Pläne teilen",
    tip_share_plans_body:         "Sage einer Vertrauensperson den Namen, den Ort und die voraussichtliche Rückkehrzeit.",
    tip_drinks_title:             "Getränk im Auge behalten",
    tip_drinks_body:              "Lass dein Getränk nie unbeaufsichtigt. Wenn du dich plötzlich unwohl fühlst, bitte sofort um Hilfe.",
    tip_financial_title:          "Niemals Finanzdaten teilen",
    tip_financial_body:           "Echte Lulou-Verbindungen fragen nie nach Geld. Jede solche Anfrage ist Betrug.",
    tip_emergency_title:          "Notfallressourcen",
    tip_emergency_body:           "Deutschland: 110/112. Österreich: 133/122. Schweiz: 117/118.",
    mp_intro:                     "Lulou basiert auf der Überzeugung, dass echte Verbindung mit echten Menschen beginnt. Mit dem Beitritt verpflichtest du dich zu diesen Grundsätzen:",
    mp_01_title:                  "Absicht über Unterhaltung",
    mp_01_body:                   "Nutze Lulou, weil du wirklich jemanden kennenlernen möchtest.",
    mp_02_title:                  "Ehrlichkeit in deinem Profil",
    mp_02_body:                   "Deine Fotos und Informationen stellen dar, wer du wirklich bist.",
    mp_03_title:                  "Respekt in jeder Nachricht",
    mp_03_body:                   "Jede Person, mit der du interagierst, verdient Respekt.",
    mp_04_title:                  "Dem Prozess folgen",
    mp_04_body:                   "Die Schritte existieren aus einem Grund. Dränge Verbindungen nicht dazu, Phasen zu überspringen.",
    mp_05_title:                  "Verpflichtungen einhalten",
    mp_05_body:                   "Wenn du einen Anruf oder ein Treffen planst, halte es ein. Wenn du absagen musst, tue es rechtzeitig.",
    mp_06_title:                  "Mit Würde gehen",
    mp_06_body:                   "Es ist in Ordnung, keine Verbindung zu spüren. Trenne dich mit Freundlichkeit.",
    mp_07_title:                  "Sicherheit zuerst — immer",
    mp_07_body:                   "Melde alles, was sich falsch anfühlt. Blockiere Belästigung sofort.",
    lic_intro:                    "Lulou Dating wurde mit Open-Source-Software erstellt. Wir danken folgenden Projekten:",
    lib_react_desc:               "Eine JavaScript-Bibliothek zum Erstellen von Benutzeroberflächen.",
    lib_vite_desc:                "Frontend-Tools der nächsten Generation.",
    lib_tailwind_desc:            "Ein Utility-First-CSS-Framework.",
    lib_radix_desc:               "Zugängliche Komponenten-Primitive.",
    lib_express_desc:             "Schnelles Web-Framework für Node.js.",
    lib_supabase_desc:            "Open-Source-Alternative zu Firebase mit Postgres.",
    lib_drizzle_desc:             "TypeScript-ORM für SQL-Datenbanken.",
    lib_tanstack_desc:            "Datenabruf und Caching für React.",
    lib_lucide_desc:              "Schöne und konsistente Open-Source-Icons.",
    lib_wouter_desc:              "Minimalistisches Routing für React.",
    lib_zod_desc:                 "TypeScript-Schema-Validierung.",
    lib_webrtc_desc:              "Echtzeit-Peer-to-Peer-Audio und -Video.",
    pprefs_intro:                 "Wir glauben, dass deine Daten dir gehören. Das sammeln wir und warum:",
    pprefs_1_title:               "Profilinformationen",
    pprefs_1_desc:                "Dein Name, Fotos und Dating-Präferenzen werden für dein Profil gespeichert. Diese Daten werden niemals verkauft.",
    pprefs_2_title:               "Nachrichten",
    pprefs_2_desc:                "Gesprächsinhalte werden auf unseren Servern gespeichert. Nachrichten werden 30 Tage nach Schließen einer Verbindung gelöscht.",
    pprefs_3_title:               "Standort (allgemein)",
    pprefs_3_desc:                "Deine Stadt oder Region wird verwendet, um dir nahegelegene Personen anzuzeigen. Wir verfolgen deinen genauen GPS-Standort nicht.",
    pprefs_4_title:               "Nutzungsanalyse",
    pprefs_4_desc:                "Anonyme Nutzungsmuster helfen uns, die App zu verbessern.",
    pprefs_5_title:               "Push-Benachrichtigungen",
    pprefs_5_desc:                "Geräte-Token werden nur für Match- und Nachrichtenmeldungen verwendet.",
    required_label:               "Erforderlich",
    pprefs_footer:                "Für weitere Details lies unsere Datenschutzrichtlinie. Zum Löschen deiner Daten nutze Herunterladen und Löschen in den Einstellungen.",
