    tip_public_body:              "Escolha sempre um local público movimentado para o primeiro encontro. Avise um amigo onde você vai.",
    tip_transport_title:          "Organize seu próprio transporte",
    tip_transport_body:           "Dirija você mesmo, use transporte público ou chame seu próprio táxi.",
    tip_share_plans_title:        "Compartilhe seus planos",
    tip_share_plans_body:         "Diga a alguém de confiança o nome da pessoa, o local e quando espera voltar.",
    tip_drinks_title:             "Cuide da sua bebida",
    tip_drinks_body:              "Nunca deixe sua bebida sem supervisão. Se se sentir mal repentinamente, peça ajuda imediatamente.",
    tip_financial_title:          "Nunca compartilhe dados financeiros",
    tip_financial_body:           "Conexões legítimas do Lulou nunca pedem dinheiro. Qualquer solicitação assim é golpe.",
    tip_emergency_title:          "Recursos de emergência",
    tip_emergency_body:           "Brasil: LIGUE 180 (violência contra mulher) ou 190 (polícia). Sempre ligue para o serviço de emergência local.",
    mp_intro:                     "O Lulou se baseia na crença de que a conexão genuína começa com pessoas genuínas. Ao se juntar, você se compromete com estes princípios:",
    mp_01_title:                  "Intenção sobre entretenimento",
    mp_01_body:                   "Use o Lulou porque genuinamente quer conhecer alguém.",
    mp_02_title:                  "Honestidade no seu perfil",
    mp_02_body:                   "Suas fotos e informações representam quem você realmente é.",
    mp_03_title:                  "Respeito em cada mensagem",
    mp_03_body:                   "Cada pessoa com quem você interage merece respeito.",
    mp_04_title:                  "Siga o processo",
    mp_04_body:                   "Os passos existem por uma razão. Não pressione conexões para pular etapas.",
    mp_05_title:                  "Cumpra seus compromissos",
    mp_05_body:                   "Se agendar uma chamada ou encontro, cumpra. Se precisar cancelar, avise com antecedência.",
    mp_06_title:                  "Saída com elegância",
