    mp_07_title:                  "Segurança em primeiro lugar — sempre",
    mp_07_body:                   "Denuncie qualquer coisa que pareça errada. Bloqueie assédio imediatamente.",
    lic_intro:                    "O Lulou Dating é construído com software de código aberto. Agradecemos os seguintes projetos:",
    lib_react_desc:               "Uma biblioteca JavaScript para criar interfaces de usuário.",
    lib_vite_desc:                "Ferramentas de frontend de próxima geração.",
    lib_tailwind_desc:            "Um framework CSS utilitário.",
    lib_radix_desc:               "Primitivos de componentes acessíveis.",
    lib_express_desc:             "Framework web rápido para Node.js.",
