    lib_drizzle_desc:             "ORM TypeScript para bancos de dados SQL.",
    lib_tanstack_desc:            "Busca e cache de dados para React.",
    lib_lucide_desc:              "Ícones open source bonitos e consistentes.",
    lib_wouter_desc:              "Roteamento minimalista para React.",
    lib_zod_desc:                 "Validação de esquemas TypeScript.",
    lib_webrtc_desc:              "Áudio e vídeo peer-to-peer em tempo real.",
    pprefs_intro:                 "Acreditamos que seus dados são seus. Aqui está exatamente o que coletamos e por quê:",
    pprefs_1_title:               "Informações do perfil",
