    pp_s1_title:                  "Informazioni che raccogliamo",
    pp_s1_body:                   "Raccogliamo le informazioni che fornisci alla creazione del profilo: nome, età, foto e preferenze. Raccogliamo anche dati di utilizzo per migliorare il servizio.",
    pp_s2_title:                  "Come usiamo le tue informazioni",
    pp_s2_body:                   "Le tue informazioni vengono utilizzate per connetterti con persone compatibili e garantire la sicurezza sulla piattaforma. Non vendiamo i tuoi dati personali a terzi.",
    pp_s3_title:                  "Foto e media",
