    pp_s4_title:                  "Conservazione dei dati",
    pp_s4_body:                   "I tuoi dati vengono conservati finché il tuo account è attivo. Alla cancellazione dell'account, i tuoi dati vengono eliminati entro 30 giorni.",
    pp_s5_title:                  "I tuoi diritti",
