    tos_s6_title:                 "Contatto",
    tos_s6_body:                  "Domande? Scrivi a legal@lulou.dating.",
    export_data_title:            "Esporta i tuoi dati personali",
    export_data_desc:             "Scarica un file JSON con le informazioni del profilo, preferenze e dettagli dell'account.",
    tip_voice_call_title:         "Inizia con una chiamata vocale",
    tip_voice_call_body:          "Il sistema di chiamate strutturato di Lulou ti permette di sentire la voce di qualcuno prima di incontrarsi.",
    tip_red_flags_title:          "Fidati dei segnali d'allarme",
    tip_red_flags_body:           "Se qualcuno ti pressa per condividere dati di contatto, chiede soldi o ti fa sentire a disagio, bloccalo e segnalalo.",
    tip_public_title:             "Incontrasi in pubblico prima",
    tip_public_body:              "Scegli sempre un luogo pubblico affollato per un primo incontro. Avvisa un amico di dove vai.",
