    tip_financial_body:           "Le connessioni legittime su Lulou non chiedono mai soldi. Qualsiasi richiesta è una truffa.",
    tip_emergency_title:          "Risorse di emergenza",
    tip_emergency_body:           "Italia: 112. Numero antiviolenza: 1522. Chiama sempre i servizi di emergenza locali.",
    mp_intro:                     "Lulou si basa sulla convinzione che la connessione genuina inizi con persone genuine. Unendoti, ti impegni con questi principi:",
    mp_01_title:                  "Intenzione sull'intrattenimento",
    mp_01_body:                   "Usa Lulou perché vuoi genuinamente conoscere qualcuno.",
    mp_02_title:                  "Onestà nel profilo",
    mp_02_body:                   "Le tue foto e informazioni rappresentano chi sei davvero.",
    mp_03_title:                  "Rispetto in ogni messaggio",
    mp_03_body:                   "Ogni persona con cui interagisci merita rispetto.",
    mp_04_title:                  "Segui il processo",
    mp_04_body:                   "I passi esistono per una ragione. Non spingere le connessioni a saltare le fasi.",
    mp_05_title:                  "Mantieni gli impegni",
    mp_05_body:                   "Se programmi una chiamata o un incontro, rispettalo. Se devi cancellare, fallo con preavviso.",
    mp_06_title:                  "Uscita con grazia",
    mp_06_body:                   "Va bene non sentire connessione. Disconnettiti con gentilezza.",
    mp_07_title:                  "Sicurezza prima — sempre",
    mp_07_body:                   "Segnala qualsiasi cosa che sembra sbagliata. Blocca le molestie immediatamente.",
    lic_intro:                    "Lulou Dating è costruito con software open source. Ringraziamo i seguenti progetti:",
    lib_react_desc:               "Una libreria JavaScript per creare interfacce utente.",
    lib_vite_desc:                "Strumenti frontend di prossima generazione.",
    lib_tailwind_desc:            "Un framework CSS utility-first.",
    lib_radix_desc:               "Primitive di componenti accessibili.",
    lib_express_desc:             "Framework web veloce per Node.js.",
    lib_supabase_desc:            "Alternativa open source a Firebase con Postgres.",
    lib_drizzle_desc:             "ORM TypeScript per database SQL.",
    lib_tanstack_desc:            "Recupero e caching dati per React.",
    lib_lucide_desc:              "Icone open source belle e coerenti.",
    lib_wouter_desc:              "Routing minimalista per React.",
    lib_zod_desc:                 "Validazione schemi TypeScript.",
    lib_webrtc_desc:              "Audio e video peer-to-peer in tempo reale.",
    pprefs_intro:                 "Crediamo che i tuoi dati siano tuoi. Ecco esattamente cosa raccogliamo e perché:",
    pprefs_1_title:               "Informazioni del profilo",
    pprefs_1_desc:                "Il tuo nome, foto e preferenze vengono archiviati per il tuo profilo. Questi dati non vengono mai venduti.",
    pprefs_2_title:               "Messaggi",
