    pp_s1_title:                  "Informatie die we verzamelen",
    pp_s1_body:                   "We verzamelen de informatie die je geeft bij het aanmaken van een profiel: naam, leeftijd, foto's en voorkeuren. We verzamelen ook gebruiksgegevens om de service te verbeteren.",
    pp_s2_title:                  "Hoe we je informatie gebruiken",
    pp_s2_body:                   "Je informatie wordt gebruikt om je te verbinden met compatibele mensen en veiligheid op het platform te waarborgen. We verkopen je persoonlijke gegevens niet aan derden.",
    pp_s3_title:                  "Foto's en media",
    pp_s3_body:                   "Foto's die je uploadt worden veilig opgeslagen. Profielfoto's zijn zichtbaar voor andere leden. We gebruiken je foto's niet om AI-modellen te trainen.",
    pp_s4_title:                  "Gegevensbewaring",
    pp_s4_body:                   "Je gegevens worden bewaard zolang je account actief is. Bij het verwijderen van je account worden je persoonlijke gegevens binnen 30 dagen verwijderd.",
    pp_s5_title:                  "Jouw rechten",
    pp_s5_body:                   "Je hebt het recht om je gegevens op elk moment in te zien, te corrigeren of te verwijderen. Je kunt een kopie downloaden via de instellingen.",
    pp_s6_title:                  "Contact",
    pp_s6_body:                   "Vragen over dit beleid? Schrijf ons op privacy@lulou.dating.",
    tos_s1_title:                 "Acceptatie van voorwaarden",
    tos_s1_body:                  "Door een account aan te maken bij Lulou ga je akkoord met deze Servicevoorwaarden.",
    tos_s2_title:                 "Geschiktheid",
    tos_s2_body:                  "Je moet 18 jaar of ouder zijn om Lulou te gebruiken.",
    tos_s3_title:                 "Acceptabel gebruik",
    tos_s3_body:                  "Behandel alle leden met respect en gebruik het platform niet voor intimidatie of illegale activiteiten.",
    tos_s4_title:                 "Eigendom van inhoud",
    tos_s4_body:                  "Je behoudt het eigendom van de foto's en inhoud die je uploadt.",
    tos_s5_title:                 "Beëindiging",
    tos_s5_body:                  "We kunnen accounts opschorten die deze voorwaarden schenden. Je kunt je account op elk moment verwijderen.",
    tos_s6_title:                 "Contact",
    tos_s6_body:                  "Vragen? Schrijf naar legal@lulou.dating.",
    export_data_title:            "Je persoonlijke gegevens exporteren",
    export_data_desc:             "Download een JSON-bestand met je profielinformatie, voorkeuren en accountgegevens.",
    tip_voice_call_title:         "Begin met een gesprek",
    tip_voice_call_body:          "Het gestructureerde gesprekssysteem van Lulou laat je iemands stem horen voordat je elkaar ontmoet.",
    tip_red_flags_title:          "Vertrouw op waarschuwingssignalen",
    tip_red_flags_body:           "Als iemand je onder druk zet om contactgegevens te delen, geld vraagt of je ongemakkelijk laat voelen, blokkeer dan en rapporteer.",
    tip_public_title:             "Ontmoet eerst in het openbaar",
    tip_public_body:              "Kies altijd een drukke openbare plek voor een eerste ontmoeting. Laat een vriend weten waar je naartoe gaat.",
    tip_transport_title:          "Regel je eigen vervoer",
    tip_transport_body:           "Rij zelf, gebruik openbaar vervoer of bel je eigen taxi.",
    tip_share_plans_title:        "Deel je plannen",
    tip_share_plans_body:         "Vertel iemand die je vertrouwt de naam, de locatie en wanneer je verwacht terug te zijn.",
    tip_drinks_title:             "Houd je drankje in de gaten",
    tip_drinks_body:              "Laat je drankje nooit onbeheerd. Als je je plotseling ziek voelt, vraag dan direct om hulp.",
    tip_financial_title:          "Deel nooit financiële gegevens",
    tip_financial_body:           "Echte Lulou-verbindingen vragen nooit om geld. Elke dergelijke aanvraag is oplichterij.",
    tip_emergency_title:          "Noodhulpbronnen",
    tip_emergency_body:           "Nederland: 112. België: 112. Crisis: Slachtofferhulp 0900-0101.",
    mp_intro:                     "Lulou is gebaseerd op de overtuiging dat echte verbinding begint met echte mensen. Door lid te worden verbind je je aan deze principes:",
    mp_01_title:                  "Intentie boven entertainment",
    mp_01_body:                   "Gebruik Lulou omdat je oprecht iemand wilt leren kennen.",
    mp_02_title:                  "Eerlijkheid in je profiel",
    mp_02_body:                   "Je foto's en informatie vertegenwoordigen wie je werkelijk bent.",
    mp_03_title:                  "Respect in elk bericht",
    mp_03_body:                   "Elke persoon met wie je interageert is een mens die respect verdient.",
    mp_04_title:                  "Volg het proces",
    mp_04_body:                   "De stappen bestaan om een reden. Dring verbindingen niet om fasen over te slaan.",
    mp_05_title:                  "Kom je verplichtingen na",
    mp_05_body:                   "Als je een gesprek of ontmoeting plant, kom dan opdagen. Als je moet annuleren, doe dit dan tijdig.",
    mp_06_title:                  "Afscheid met gratie",
    mp_06_body:                   "Het is oké om geen verbinding te voelen. Verbreek de verbinding met vriendelijkheid.",
    mp_07_title:                  "Veiligheid eerst — altijd",
    mp_07_body:                   "Rapporteer alles wat verkeerd aanvoelt. Blokkeer intimidatie onmiddellijk.",
    lic_intro:                    "Lulou Dating is gebouwd met open-sourcesoftware. We erkennen dankbaar de volgende projecten:",
    lib_react_desc:               "Een JavaScript-bibliotheek voor het bouwen van gebruikersinterfaces.",
    lib_vite_desc:                "Volgende generatie frontend-tools.",
    lib_tailwind_desc:            "Een utility-first CSS-framework.",
    lib_radix_desc:               "Toegankelijke componentprimitieven.",
    lib_express_desc:             "Snel webframework voor Node.js.",
    lib_supabase_desc:            "Open-source alternatief voor Firebase met Postgres.",
    lib_drizzle_desc:             "TypeScript ORM voor SQL-databases.",
    lib_tanstack_desc:            "Gegevens ophalen en cachen voor React.",
    lib_lucide_desc:              "Mooie en consistente open-source iconen.",
    lib_wouter_desc:              "Minimalistisch routing voor React.",
    lib_zod_desc:                 "TypeScript-schemavalidatie.",
    lib_webrtc_desc:              "Realtime peer-to-peer audio en video.",
    pprefs_intro:                 "We geloven dat jouw gegevens van jou zijn. Dit is precies wat we verzamelen en waarom:",
    pprefs_1_title:               "Profielinformatie",
    pprefs_1_desc:                "Je naam, foto's en voorkeuren worden opgeslagen voor je profiel en matching. Ze worden nooit verkocht.",
    pprefs_2_title:               "Berichten",
    pprefs_2_desc:                "De inhoud van gesprekken wordt opgeslagen op onze servers. Berichten worden 30 dagen na het sluiten van een verbinding verwijderd.",
    pprefs_3_title:               "Locatie (algemeen)",
    pprefs_3_desc:                "Je stad of regio wordt gebruikt om mensen in de buurt te tonen. We volgen je exacte GPS-locatie niet.",
    pprefs_4_title:               "Gebruiksanalyse",
    pprefs_4_desc:                "Anonieme gebruikspatronen helpen ons de app te verbeteren.",
    pprefs_5_title:               "Pushmeldingen",
