    tip_red_flags_title:          "Ufaj sygnałom ostrzegawczym",
    tip_red_flags_body:           "Jeśli ktoś naciska cię na podanie danych kontaktowych, prosi o pieniądze lub sprawia, że czujesz się nieswojo, zablokuj go i zgłoś.",
