    tip_emergency_body:           "Polska: 112/997. Niemcy: 110/112. USA: Crisis Text Line — wyślij HOME na 741741.",
    mp_intro:                     "Lulou opiera się na przekonaniu, że prawdziwe połączenie zaczyna się od prawdziwych ludzi. Dołączając, zobowiązujesz się do tych zasad:",
    mp_01_title:                  "Intencja ponad rozrywkę",
    mp_01_body:                   "Używaj Lulou, ponieważ naprawdę chcesz kogoś poznać.",
    mp_02_title:                  "Szczerość w profilu",
    mp_02_body:                   "Twoje zdjęcia i informacje przedstawiają, kim naprawdę jesteś.",
    mp_03_title:                  "Szacunek w każdej wiadomości",
    mp_03_body:                   "Każda osoba, z którą interagujesz, jest człowiekiem zasługującym na szacunek.",
    mp_04_title:                  "Podążaj za procesem",
    mp_04_body:                   "Etapy istnieją z powodu. Nie naciskaj połączeń, żeby pomijały etapy.",
    mp_05_title:                  "Dotrzymuj zobowiązań",
    mp_05_body:                   "Jeśli planujesz rozmowę lub spotkanie, staw się. Jeśli musisz anulować, zrób to z wyprzedzeniem.",
    mp_06_title:                  "Odchodź z gracją",
    mp_06_body:                   "W porządku nie czuć połączenia. Rozłącz się z uprzejmością.",
    mp_07_title:                  "Bezpieczeństwo przede wszystkim — zawsze",
    mp_07_body:                   "Zgłaszaj wszystko, co wydaje się złe. Natychmiast blokuj nękanie.",
    lic_intro:                    "Lulou Dating jest zbudowane z oprogramowania open source. Z wdzięcznością uznajemy następujące projekty:",
    lib_react_desc:               "Biblioteka JavaScript do budowania interfejsów użytkownika.",
    lib_vite_desc:                "Narzędzia frontend nowej generacji.",
    lib_tailwind_desc:            "Framework CSS oparty na utility.",
    lib_radix_desc:               "Dostępne prymitywy komponentów.",
    lib_express_desc:             "Szybki framework webowy dla Node.js.",
    lib_supabase_desc:            "Open-source alternatywa dla Firebase z Postgres.",
    lib_drizzle_desc:             "TypeScript ORM dla baz danych SQL.",
    lib_tanstack_desc:            "Pobieranie i buforowanie danych dla React.",
    lib_lucide_desc:              "Piękne i spójne ikony open source.",
    lib_wouter_desc:              "Minimalistyczny routing dla React.",
    lib_zod_desc:                 "Walidacja schematu TypeScript.",
    lib_webrtc_desc:              "Audio i wideo peer-to-peer w czasie rzeczywistym.",
