    pp_s1_title:                  "Информация, которую мы собираем",
    pp_s1_body:                   "Мы собираем информацию, которую вы предоставляете при создании профиля: имя, возраст, фото и предпочтения. Мы также собираем данные об использовании для улучшения сервиса.",
    pp_s2_title:                  "Как мы используем вашу информацию",
    pp_s2_body:                   "Ваша информация используется для соединения с совместимыми людьми и обеспечения безопасности на платформе. Мы не продаём ваши личные данные третьим лицам.",
    pp_s3_title:                  "Фото и медиа",
    pp_s3_body:                   "Загружаемые фото хранятся безопасно. Фото профиля видны другим участникам. Мы не используем ваши фото для обучения ИИ.",
    pp_s4_title:                  "Хранение данных",
