    tip_drinks_title:             "Следите за напитком",
    tip_drinks_body:              "Никогда не оставляйте напиток без присмотра. Если вдруг почувствуете себя плохо, немедленно попросите о помощи.",
    tip_financial_title:          "Никогда не делитесь финансовыми данными",
