    mp_intro:                     "Lulou основан на убеждении, что настоящая связь начинается с настоящих людей. Присоединяясь, вы обязуетесь следовать этим принципам:",
    mp_01_title:                  "Намерение важнее развлечения",
    mp_01_body:                   "Используйте Lulou потому, что вы искренне хотите кого-то встретить.",
    mp_02_title:                  "Честность в профиле",
    mp_02_body:                   "Ваши фото и информация отражают то, кем вы действительно являетесь.",
    mp_03_title:                  "Уважение в каждом сообщении",
    mp_03_body:                   "Каждый человек, с которым вы общаетесь, заслуживает уважения.",
    mp_04_title:                  "Следуйте процессу",
