    mp_06_title:                  "Уходите достойно",
    mp_06_body:                   "Нормально не чувствовать связи. Расставайтесь с добротой.",
    mp_07_title:                  "Безопасность прежде всего — всегда",
    mp_07_body:                   "Сообщайте обо всём, что кажется неправильным. Немедленно блокируйте преследование.",
    lic_intro:                    "Lulou Dating создан с использованием программного обеспечения с открытым исходным кодом. Мы с благодарностью признаём следующие проекты:",
    lib_react_desc:               "Библиотека JavaScript для создания пользовательских интерфейсов.",
