    tos_s1_title: "条款接受",
    tos_s1_body: "通过在Lulou上创建账户，你同意这些服务条款。如果你不同意，请不要使用该平台。",
    tos_s2_title: "资格要求",
    tos_s2_body: "你必须年满18岁才能使用Lulou。通过注册，你确认满足此要求。我们可能随时要求验证。",
    tos_s3_title: "可接受的使用",
    tos_s3_body: "你同意尊重所有会员、在个人资料中提供真实信息、在早期消息阶段不分享联系方式，以及不将平台用于商业招揽、骚扰或非法活动。",
    tos_s4_title: "内容所有权",
    tos_s4_body: "你保留对你上传的照片和内容的所有权。通过上传，你授予Lulou非独家许可，作为服务的一部分向其他会员展示该内容。",
    tos_s5_title: "终止",
    tos_s5_body: "我们可能暂停或终止违反这些条款的账户。你可以随时从设置页面删除你的账户。",
    tos_s6_title: "联系方式",
    tos_s6_body: "有问题？请发邮件至legal@lulou.dating。",
    export_data_title: "导出你的个人数据",
    export_data_desc: "下载一个包含你个人资料信息、偏好和账户详情的JSON文件。出于隐私原因，不包含消息内容。",
    tip_voice_call_title: "从语音通话开始",
    tip_voice_call_body: "Lulou的结构化通话系统让你在见面前听到对方的声音。注意他们让你感觉如何。",
    tip_red_flags_title: "尽早相信红旗信号",
    tip_red_flags_body: "如果有人催你分享联系方式、要求金钱或让你感到不舒服，立即屏蔽并举报他们。",
    tip_public_title: "首次见面选择公共场所",
    tip_public_body: "首次见面始终选择繁忙的公共场所——咖啡馆、公园或购物区。告诉朋友或家人你要去哪里。",
    tip_transport_title: "安排自己的交通",
    tip_transport_body: "自己驾车、乘坐公共交通或预订自己的出租车往返约会，这样你可以控制离开时间。",
    tip_share_plans_title: "分享你的计划",
    tip_share_plans_body: "告诉你信任的人你要见的人的名字、地点以及你预计回来的时间。在约会期间与他们保持联系。",
    tip_drinks_title: "注意你的饮品",
    tip_drinks_body: "不要让你的饮品无人看管。如果你突然感到不适，立即向工作人员求助。",
    tip_financial_title: "绝不分享财务信息",
    tip_financial_body: "Lulou上的合法连接绝不会要求金钱、银行详情或礼品卡。任何此类请求都是骗局——请举报。",
    tip_emergency_title: "紧急资源",
    tip_emergency_body: "在英国：受害者支持 0808 168 9111。在美国：危机短信线——发送HOME到741741。紧急情况请拨打999或911。",
    mp_intro: "Lulou建立在真实连接始于真实人这一信念上。通过加入，你承诺遵守这些原则：",
    mp_01_title: "意图而非娱乐",
    mp_01_body: "使用Lulou是因为你真的想认识某人。不是为了收集匹配、打发时间或获得认可。",
    mp_02_title: "个人资料的诚实",
    mp_02_body: "你的照片和信息代表你真实的自己——近期的、准确的、属于你的。没有扭曲现实的滤镜，没有库存照片，没有误导性的自我介绍。",
    mp_03_title: "每条消息都要尊重",
    mp_03_body: "你互动的每个人都是值得尊重的人。以你希望被对待的方式去沟通。",
    mp_04_title: "遵循流程",
    mp_04_body: "从匹配到通话再到见面的步骤是有原因的。尊重这个结构。不要施压连接跳过阶段或过早分享联系方式。",
    mp_05_title: "承诺了就要出现",
    mp_05_body: "如果你安排了通话或会面，请履行承诺。如果需要取消，请提前通知并解释。",
    mp_06_title: "优雅地退出",
    mp_06_body: "没有感受到连接是可以的。取消匹配或说你感觉不对——但要友善地说。消失不是优雅的。",
    mp_07_title: "安全第一——始终",
    mp_07_body: "举报任何感觉不对的事情。立即屏蔽骚扰。你的安全比礼貌更重要。",
    lic_intro: "Lulou Dating使用开源软件构建。我们衷心感谢以下项目：",
    lib_react_desc: "用于构建用户界面的JavaScript库。",
    lib_vite_desc: "下一代前端工具。",
    lib_tailwind_desc: "实用优先的CSS框架。",
    lib_radix_desc: "可访问的组件原语。",
    lib_express_desc: "快速、无偏见的Node.js网络框架。",
    lib_supabase_desc: "带有Postgres的开源Firebase替代品。",
    lib_drizzle_desc: "用于SQL数据库的TypeScript ORM。",
    lib_tanstack_desc: "强大的React数据获取和缓存。",
    lib_lucide_desc: "美观且一致的开源图标。",
    lib_wouter_desc: "React的极简路由。",
    lib_zod_desc: "TypeScript优先的模式验证。",
    lib_webrtc_desc: "实时点对点音视频。",
    pprefs_intro: "我们相信你的数据是你的。以下是我们收集的内容和原因：",
    pprefs_1_title: "个人资料信息",
    pprefs_1_desc: "你的姓名、照片和约会偏好被存储以支持你的个人资料和匹配。此数据绝不会出售给第三方。",
    pprefs_2_title: "消息",
    pprefs_2_desc: "对话内容存储在我们的服务器上以传递你的消息。连接关闭30天后，消息将被删除。",
    pprefs_3_title: "位置（一般）",
