    pp_s1_title: "我們收集的資訊",
    pp_s1_body: "我們收集你在建立個人資料時提供的資訊：姓名、年齡、照片和偏好。我們還收集使用資料，如互動、滑動和訊息時間戳記（非訊息內容），以改善服務。",
    pp_s2_title: "我們如何使用你的資訊",
    pp_s2_body: "你的資訊用於將你與合適的人配對、個性化你的體驗、確保平台安全以及與你溝通帳戶事項。我們不會將你的個人資料出售給第三方。",
    pp_s3_title: "照片和媒體",
    pp_s3_body: "你上傳的照片安全儲存在我們的雲端基礎設施中。個人資料照片對其他會員可見。我們不使用你的照片訓練AI模型。",
    pp_s4_title: "資料保留",
    pp_s4_body: "在你的帳戶處於活躍狀態時，你的資料會被保留。當你刪除帳戶時，你的個人資料將在30天內被移除。一些匿名使用統計資料可能會被保留用於分析。",
    pp_s5_title: "你的權利",
    pp_s5_body: "你有權隨時存取、更正或刪除你的資料。你可以從設定中的「下載我的資料」部分下載你資料的副本。如需進一步請求，請聯繫privacy@lulou.dating。",
    pp_s6_title: "聯絡方式",
    pp_s6_body: "對此政策有疑問？請傳送電子郵件至privacy@lulou.dating。",
    tos_s1_title: "條款接受",
    tos_s1_body: "透過在Lulou上建立帳戶，你同意這些服務條款。如果你不同意，請不要使用該平台。",
    tos_s2_title: "資格要求",
    tos_s2_body: "你必須年滿18歲才能使用Lulou。透過註冊，你確認滿足此要求。我們可能隨時要求驗證。",
    tos_s3_title: "可接受的使用",
    tos_s3_body: "你同意尊重所有會員、在個人資料中提供真實資訊、在早期訊息階段不分享聯絡方式，以及不將平台用於商業招攬、騷擾或非法活動。",
    tos_s4_title: "內容所有權",
    tos_s4_body: "你保留對你上傳的照片和內容的所有權。透過上傳，你授予Lulou非獨家授權，作為服務的一部分向其他會員展示該內容。",
    tos_s5_title: "終止",
    tos_s5_body: "我們可能暫停或終止違反這些條款的帳戶。你可以隨時從設定頁面刪除你的帳戶。",
    tos_s6_title: "聯絡方式",
    tos_s6_body: "有問題？請傳送電子郵件至legal@lulou.dating。",
    export_data_title: "匯出你的個人資料",
    export_data_desc: "下載一個包含你個人資料資訊、偏好和帳戶詳情的JSON檔案。出於隱私原因，不包含訊息內容。",
    tip_voice_call_title: "從語音通話開始",
    tip_voice_call_body: "Lulou的結構化通話系統讓你在見面前聽到對方的聲音。注意他們讓你感覺如何。",
    tip_red_flags_title: "盡早相信紅旗信號",
    tip_red_flags_body: "如果有人催你分享聯絡方式、要求金錢或讓你感到不舒服，立即封鎖並舉報他們。",
    tip_public_title: "首次見面選擇公共場所",
    tip_public_body: "首次見面始終選擇繁忙的公共場所——咖啡館、公園或購物區。告訴朋友或家人你要去哪裡。",
    tip_transport_title: "安排自己的交通",
    tip_transport_body: "自己駕車、搭乘大眾運輸或預訂自己的計程車往返約會，這樣你可以控制離開時間。",
    tip_share_plans_title: "分享你的計畫",
    tip_share_plans_body: "告訴你信任的人你要見的人的名字、地點以及你預計回來的時間。在約會期間與他們保持聯繫。",
    tip_drinks_title: "注意你的飲品",
    tip_drinks_body: "不要讓你的飲品無人看管。如果你突然感到不適，立即向工作人員求助。",
    tip_financial_title: "絕不分享財務資訊",
    tip_financial_body: "Lulou上的合法連接絕不會要求金錢、銀行詳情或禮品卡。任何此類請求都是詐騙——請舉報。",
    tip_emergency_title: "緊急資源",
    tip_emergency_body: "在英國：受害者支持 0808 168 9111。在美國：危機簡訊線——傳送HOME到741741。緊急情況請撥打999或911。",
    mp_intro: "Lulou建立在真實連接始於真實人這一信念上。透過加入，你承諾遵守這些原則：",
    mp_01_title: "意圖而非娛樂",
    mp_01_body: "使用Lulou是因為你真的想認識某人。不是為了收集配對、打發時間或獲得認可。",
    mp_02_title: "個人資料的誠實",
    mp_02_body: "你的照片和資訊代表你真實的自己——近期的、準確的、屬於你的。沒有扭曲現實的濾鏡，沒有庫存照片，沒有誤導性的自我介紹。",
    mp_03_title: "每條訊息都要尊重",
    mp_03_body: "你互動的每個人都是值得尊重的人。以你希望被對待的方式去溝通。",
    mp_04_title: "遵循流程",
    mp_04_body: "從配對到通話再到見面的步驟是有原因的。尊重這個結構。不要施壓連接跳過階段或過早分享聯絡方式。",
    mp_05_title: "承諾了就要出現",
    mp_05_body: "如果你安排了通話或會面，請履行承諾。如果需要取消，請提前通知並解釋。",
    mp_06_title: "優雅地退出",
    mp_06_body: "沒有感受到連接是可以的。取消配對或說你感覺不對——但要友善地說。消失不是優雅的。",
    mp_07_title: "安全第一——始終",
    mp_07_body: "舉報任何感覺不對的事情。立即封鎖騷擾。你的安全比禮貌更重要。",
    lic_intro: "Lulou Dating使用開源軟體構建。我們衷心感謝以下專案：",
