    pp_s1_title: "हम जो जानकारी एकत्र करते हैं",
    pp_s1_body: "हम प्रोफ़ाइल बनाते समय आपके द्वारा दी गई जानकारी एकत्र करते हैं: नाम, उम्र, तस्वीरें और पसंद। हम सेवा सुधारने के लिए उपयोग डेटा जैसे इंटरैक्शन, स्वाइप और संदेश टाइमस्टैम्प (संदेश सामग्री नहीं) भी एकत्र करते हैं।",
    pp_s2_title: "हम आपकी जानकारी कैसे उपयोग करते हैं",
    pp_s2_body: "आपकी जानकारी का उपयोग आपको अनुकूल लोगों से मिलाने, आपके अनुभव को व्यक्तिगत बनाने, प्लेटफॉर्म पर सुरक्षा सुनिश्चित करने और आपके खाते के बारे में संवाद करने के लिए किया जाता है। हम आपके व्यक्तिगत डेटा को तीसरे पक्ष को नहीं बेचते।",
    pp_s3_title: "तस्वीरें और मीडिया",
    pp_s3_body: "आपके द्वारा अपलोड की गई तस्वीरें हमारे क्लाउड इन्फ्रास्ट्रक्चर में सुरक्षित रूप से संग्रहीत हैं। प्रोफ़ाइल तस्वीरें अन्य सदस्यों को दिखाई देती हैं। हम आपकी तस्वीरों का उपयोग AI मॉडल प्रशिक्षण के लिए नहीं करते।",
    pp_s4_title: "डेटा प्रतिधारण",
    pp_s4_body: "आपका डेटा तब तक संग्रहीत रहता है जब तक आपका खाता सक्रिय है। जब आप खाता हटाते हैं, तो आपका व्यक्तिगत डेटा 30 दिनों के भीतर हटा दिया जाता है। कुछ गुमनाम उपयोग आंकड़े विश्लेषण के लिए रखे जा सकते हैं।",
    pp_s5_title: "आपके अधिकार",
    pp_s5_body: "आपको किसी भी समय अपने डेटा तक पहुंचने, सुधारने या हटाने का अधिकार है। आप सेटिंग में \"मेरा डेटा डाउनलोड करें\" अनुभाग से अपने डेटा की प्रति डाउनलोड कर सकते हैं। आगे के अनुरोधों के लिए, privacy@lulou.dating से संपर्क करें।",

    pp_s6_title: "संपर्क",
    pp_s6_body: "इस नीति के बारे में प्रश्न? privacy@lulou.dating पर ईमेल करें।",
