    ph_city_state: "Mji, Jimbo",
    intent_meaningful: "Uhusiano wa Maana",
    intent_intentional: "Kupiga Miadi kwa Makusudi",
    intent_open_serious: "Wazi lakini wa Kweli",
    style_slow: "Polepole na Makusudi",
    style_steady: "Thabiti na Kasi",
    style_ready: "Tayari Kukutana Hivi Karibuni",
    pp_updated: "Ilisasishwa mara ya mwisho: Januari 2025",
    pp_s1_title: "Taarifa Tunazokusanya",
    pp_s1_body: "Tunakusanya taarifa unazotoa unapounda wasifu: jina, umri, picha, na mapenzi. Pia tunakusanya data ya matumizi kama vile mwingiliano, kuteleza, na alama za wakati wa ujumbe (si maudhui ya ujumbe) kuboresha huduma.",
    pp_s2_title: "Jinsi Tunavyotumia Taarifa Zako",
    pp_s2_body: "Taarifa zako zinatumika kukuoanisha na watu wanaofaa, kubuni uzoefu wako, kuhakikisha usalama kwenye jukwaa, na kuwasiliana nawe kuhusu akaunti yako. Hatuuzi data yako ya kibinafsi kwa watu wa tatu.",
    pp_s3_title: "Picha na Midia",
    pp_s3_body: "Picha unazopakia zimehifadhiwa salama katika miundombinu yetu ya wingu. Picha za wasifu zinaonekana kwa wanachama wengine. Hatutumii picha zako kufunza mifano ya AI.",
    pp_s4_title: "Uhifadhi wa Data",
    pp_s4_body: "Data yako inahifadhiwa akaunti yako ikiwa hai. Unapoifuta akaunti, data yako ya kibinafsi inaondolewa ndani ya siku 30. Takwimu fulani za matumizi zisizo na utambulisho zinaweza kuhifadhiwa kwa uchambuzi.",
    pp_s5_title: "Haki Zako",
    pp_s5_body: "Una haki ya kufikia, kusahihisha, au kufuta data yako wakati wowote. Unaweza kupakua nakala ya data yako kutoka sehemu ya \"Pakua data yangu\" katika mipangilio. Kwa maombi zaidi, wasiliana na privacy@lulou.dating.",

    pp_s6_title: "Mawasiliano",
    pp_s6_body: "Maswali kuhusu sera hii? Tutumie barua pepe kwa privacy@lulou.dating.",
    tos_s1_title: "Kukubaliana na Masharti",
    tos_s1_body: "Kwa kuunda akaunti kwenye Lulou, unakubaliana na Masharti haya ya Huduma. Usipokubaliana, tafadhali usitumie jukwaa.",
    tos_s2_title: "Ustahili",
    tos_s2_body: "Lazima uwe na umri wa miaka 18 au zaidi kutumia Lulou. Kwa kusajili, unathibitisha kwamba unakidhi haja hii.",
    tos_s3_title: "Matumizi Yanayokubalika",
    tos_s3_body: "Unakubaliana kuheshimu wanachama wote, kutoa taarifa za kweli kwenye wasifu wako, kutoshiriki maelezo ya mawasiliano katika hatua za mapema za ujumbe, na kutotumia jukwaa kwa uombezi wa kibiashara, unyanyasaji, au shughuli za kisheria.",
    tos_s4_title: "Umiliki wa Maudhui",
    tos_s4_body: "Unabaki na umiliki wa picha na maudhui unayopakia. Kwa kupakia, unaitoa Lulou leseni isiyokuwa ya kipekee ya kuonyesha maudhui hayo kwa wanachama wengine kama sehemu ya huduma.",
    tos_s5_title: "Kusimamishwa",
    tos_s5_body: "Tunaweza kusimamisha au kumalizisha akaunti zinazokiuka masharti haya. Unaweza kufuta akaunti yako wakati wowote kutoka ukurasa wa Mipangilio.",
    tos_s6_title: "Mawasiliano",
    tos_s6_body: "Maswali? Tutumie barua pepe kwa legal@lulou.dating.",
    export_data_title: "Hamisha data yako ya kibinafsi",
    export_data_desc: "Pakua faili ya JSON iliyo na taarifa za wasifu wako, mapenzi, na maelezo ya akaunti. Maudhui ya ujumbe hayajumuishwi kwa sababu za faragha.",
    tip_voice_call_title: "Anza na simu ya sauti",
    tip_voice_call_body: "Mfumo wa simu uliopangwa wa Lulou unakuruhusu kusikia sauti ya mtu kabla ya kukutana. Makini jinsi wanavyokufanya uhisi.",
    tip_red_flags_title: "Amini bendera nyekundu mapema",
    tip_red_flags_body: "Mtu akikusukuma kushiriki maelezo ya mawasiliano, akiomba pesa, au akikufanya usijisikie vizuri, mzuie na umripoti mara moja.",
    tip_public_title: "Kutana mahali pa umma kwanza",
    tip_public_body: "Daima chagua mahali pa umma, penye watu wengi kwa mkutano wa kwanza — cafe, bustani, au eneo la ununuzi.",
    tip_transport_title: "Panga usafiri wako mwenyewe",
    tip_transport_body: "Endesha mwenyewe, tumia usafiri wa umma, au piga taxi yako mwenyewe kwenda na kurudi miadi ili udhibiti lini unaondoka.",
    tip_share_plans_title: "Shiriki mipango yako",
    tip_share_plans_body: "Mwambie mtu unayemwamini jina la mtu unayekutana naye, mahali, na unatarajia kurudi lini.",
    tip_drinks_title: "Angalia vinywaji vyako",
    tip_drinks_body: "Usiacha kinywaji chako bila ulinzi. Ukihisi vibaya ghafla, omba msaada wa mwanakazi mara moja.",
    tip_financial_title: "Usishiriki maelezo ya fedha kamwe",
    tip_financial_body: "Miunganiko halisi kwenye Lulou kamwe haitaomba pesa, maelezo ya benki, au kadi za zawadi.",
    tip_emergency_title: "Rasilimali za dharura",
    tip_emergency_body: "UK: Msaada wa Waathiriwa 0808 168 9111. US: Crisis Text Line — tuma HOME kwa 741741. Daima piga simu 999 au 911 dharura.",
    mp_intro: "Lulou imejengwa juu ya imani kwamba miunganiko ya kweli huanza na watu wa kweli. Kwa kujiunga, unaahidi kufuata kanuni hizi:",
    mp_01_title: "Nia, si burudani",
    mp_01_body: "Tumia Lulou kwa sababu unataka kweli kukutana na mtu. Si kukusanya mechi, kupoteza muda, au kujithibitishia.",
    mp_02_title: "Uaminifu kwenye wasifu",
    mp_02_body: "Picha na taarifa zako zinawakilisha ni nani wewe kweli — za hivi karibuni, sahihi, na za kweli zako.",
    mp_03_title: "Heshima katika kila ujumbe",
    mp_03_body: "Kila mtu unayeingiliana naye ni binadamu anayestahili heshima. Wasiliana jinsi unavyotaka kuwasiliana nawe.",
    mp_04_title: "Fuata mchakato",
    mp_04_body: "Hatua kutoka mechi hadi simu hadi kukutana zipo kwa sababu. Heshimu muundo. Usisukume miunganiko kuruka hatua au kushiriki maelezo ya mawasiliano mapema.",
    mp_05_title: "Hudhuria unapojitolea",
    mp_05_body: "Ukipanga simu au mkutano, iheshimu. Ukihitaji kughairi, fanya kwa taarifa na maelezo.",
    mp_06_title: "Kuondoka kwa heshima",
    mp_06_body: "Ni sawa kutohisi miunganiko. Toa mechi au sema huhisi — lakini fanya kwa upole. Kutoweka si kwa heshima.",
    mp_07_title: "Usalama kwanza — daima",
    mp_07_body: "Ripoti chochote kinachohisi kibaya. Zuia unyanyasaji mara moja. Usalama wako ni muhimu zaidi kuliko kuwa na adabu.",
    lic_intro: "Lulou Dating imejengwa na programu ya chanzo wazi. Tunashukuru kwa moyo miradi ifuatayo:",
    lib_react_desc: "Maktaba ya JavaScript kwa kujenga kiolesura cha mtumiaji.",
    lib_vite_desc: "Zana za kizazi kijacho cha mbele.",
    lib_tailwind_desc: "Mfumo wa CSS wa matumizi kwanza.",
    lib_radix_desc: "Sehemu zinazoweza kufikiwa za msingi.",
    lib_express_desc: "Mfumo wa wavuti wa Node.js haraka na bila imani.",
    lib_supabase_desc: "Mbadala wa Firebase wa chanzo wazi na Postgres.",
    lib_drizzle_desc: "TypeScript ORM kwa hifadhidata za SQL.",
    lib_tanstack_desc: "Upataji wa data wenye nguvu na kuhifadhi kwa React.",
    lib_lucide_desc: "Ikoni nzuri na za kufanana za chanzo wazi.",
    lib_wouter_desc: "Uelekezaji wa chini kabisa kwa React.",
    lib_zod_desc: "Uthibitishaji wa mpango wa TypeScript kwanza.",
    lib_webrtc_desc: "Sauti na video ya wakati halisi kwa rika hadi rika.",
    pprefs_intro: "Tunaamini data yako ni yako. Hivi ndivyo tunachokusanya na kwa nini:",
    pprefs_1_title: "Taarifa za wasifu",
    pprefs_1_desc: "Jina lako, picha, na mapenzi ya kupiga miadi yamehifadhiwa kulisha wasifu wako na kuoanisha. Data hii haijawahi kuuzwa kwa watu wa tatu.",
    pprefs_2_title: "Ujumbe",
    pprefs_2_desc: "Maudhui ya mazungumzo yamehifadhiwa kwenye seva zetu kutoa ujumbe wako. Ujumbe unafutwa siku 30 baada ya muunganiko kufungwa.",
    pprefs_3_title: "Mahali (kwa ujumla)",
    pprefs_3_desc: "Mji au mkoa wako unatumika kuonyesha watu walio karibu nawe. Hatuufuatilii mahali pako halisi pa GPS.",
    pprefs_4_title: "Uchambuzi wa matumizi",
    pprefs_4_desc: "Mifumo ya matumizi isiyojulikana inatusaidia kuboresha programu. Hakuna taarifa zinazotambulika za kibinafsi zinazojumuishwa.",
    pprefs_5_title: "Arifa za kusukuma",
    pprefs_5_desc: "Tokeni za kifaa zinatumika tu kutoa arifa za mechi na ujumbe. Unaweza kulemaza hii katika mipangilio ya kifaa chako.",
    required_label: "Inahitajika",
    pprefs_footer: "Kwa maelezo kamili, soma Sera yetu ya Faragha. Kuomba ufutaji wa data yako, tumia chaguo la Pakua na Futa katika mipangilio.",
    edit_phone_title: "Hariri Nambari ya Simu",
